CREATE TABLE "core_metadata" ("id" INTEGER NOT NULL DEFAULT 1, "application_version" TEXT NULL, "snapshot_schema_version" INTEGER NULL, "snapshot_created_at_utc" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "desk_tiles" ("id" TEXT NOT NULL, "desk_id" TEXT NOT NULL REFERENCES desks (id) ON DELETE CASCADE, "position" INTEGER NOT NULL, "sheet_ref" TEXT NOT NULL, "view_id" TEXT NULL REFERENCES saved_views (id) ON DELETE CASCADE, PRIMARY KEY ("id"));
CREATE TABLE "desks" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "starter_key" TEXT NULL CHECK(starter_key IS NULL OR starter_key IN ('today', 'weeklyReview', 'monthClose')), "layout" TEXT NOT NULL CHECK(layout IN ('single', 'twoColumns', 'mainAndSide')), "position" INTEGER NOT NULL, "revision" INTEGER NOT NULL CHECK(revision >= 0), PRIMARY KEY ("id"), UNIQUE (starter_key));
CREATE TABLE "employments" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "legal_label" TEXT NULL, "status" TEXT NOT NULL, "created_at_utc_micros" INTEGER NOT NULL, "updated_at_utc_micros" INTEGER NOT NULL, "revision" INTEGER NOT NULL CHECK(revision >= 0), PRIMARY KEY ("id"));
CREATE TABLE "pay_agreements" ("id" TEXT NOT NULL, "employment_id" TEXT NOT NULL REFERENCES employments (id) ON DELETE RESTRICT, "version" INTEGER NOT NULL CHECK(version > 0), "effective_start" TEXT NOT NULL, "effective_end" TEXT NULL, "hourly_rate_micro_eur" INTEGER NOT NULL CHECK(hourly_rate_micro_eur > 0), "basis" TEXT NOT NULL, "overtime_threshold_minutes" INTEGER NOT NULL CHECK(overtime_threshold_minutes > 0), "overtime_multiplier_numerator" INTEGER NOT NULL CHECK(overtime_multiplier_numerator > 0), "overtime_multiplier_denominator" INTEGER NOT NULL CHECK(overtime_multiplier_denominator > 0), "night_enabled" INTEGER NOT NULL CHECK ("night_enabled" IN (0, 1)), "night_start_minute" INTEGER NOT NULL CHECK(night_start_minute BETWEEN 0 AND 1439), "night_end_minute" INTEGER NOT NULL CHECK(night_end_minute BETWEEN 0 AND 1439), "night_multiplier_numerator" INTEGER NOT NULL CHECK(night_multiplier_numerator > 0), "night_multiplier_denominator" INTEGER NOT NULL CHECK(night_multiplier_denominator > 0), "holiday_calendar" TEXT NOT NULL CHECK(holiday_calendar IN ('none', 'lithuania')), "holiday_multiplier_numerator" INTEGER NOT NULL CHECK(holiday_multiplier_numerator > 0), "holiday_multiplier_denominator" INTEGER NOT NULL CHECK(holiday_multiplier_denominator > 0), "premium_stacking" TEXT NOT NULL CHECK(premium_stacking IN ('highest', 'additive', 'multiplicative')), "label" TEXT NULL, "note" TEXT NULL, "created_at_utc_micros" INTEGER NOT NULL, "revision" INTEGER NOT NULL CHECK(revision >= 0), PRIMARY KEY ("id"), CHECK (effective_end IS NULL OR effective_end >= effective_start), CHECK (overtime_multiplier_numerator >= overtime_multiplier_denominator), CHECK (night_multiplier_numerator >= night_multiplier_denominator), CHECK (holiday_multiplier_numerator >= holiday_multiplier_denominator), CHECK (night_start_minute <> night_end_minute), UNIQUE (employment_id, version));
CREATE TABLE "pay_periods" ("id" TEXT NOT NULL, "employment_id" TEXT NOT NULL REFERENCES employments (id) ON DELETE RESTRICT, "start" TEXT NOT NULL, "end" TEXT NOT NULL, "label" TEXT NULL, "state" TEXT NOT NULL, "created_at_utc_micros" INTEGER NOT NULL, "updated_at_utc_micros" INTEGER NOT NULL, "revision" INTEGER NOT NULL CHECK(revision >= 0), PRIMARY KEY ("id"), CHECK ("end" >= start));
CREATE TABLE "payslips" ("id" TEXT NOT NULL, "period_id" TEXT NOT NULL REFERENCES pay_periods (id) ON DELETE RESTRICT, "issued_date" TEXT NOT NULL, "paid_date" TEXT NULL, "amount_minor_units" INTEGER NOT NULL CHECK(amount_minor_units > 0), "currency" TEXT NOT NULL, "basis" TEXT NOT NULL, "gross_minor_units" INTEGER NULL CHECK(gross_minor_units IS NULL OR gross_minor_units >= 0), "net_minor_units" INTEGER NULL CHECK(net_minor_units IS NULL OR net_minor_units >= 0), "deduction_minor_units" INTEGER NULL CHECK(deduction_minor_units IS NULL OR deduction_minor_units >= 0), "reference" TEXT NULL, "note" TEXT NULL, "state" TEXT NOT NULL, "void_reason" TEXT NULL, "replacement_payslip_id" TEXT NULL REFERENCES payslips (id) ON DELETE RESTRICT, "replaced_payslip_id" TEXT NULL REFERENCES payslips (id) ON DELETE RESTRICT, "created_at_utc_micros" INTEGER NOT NULL, "updated_at_utc_micros" INTEGER NOT NULL, "revision" INTEGER NOT NULL CHECK(revision >= 0), PRIMARY KEY ("id"));
CREATE TABLE "preferences" ("key" TEXT NOT NULL CHECK(key IN ('appearance')), "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "record_events" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "record_kind" TEXT NOT NULL, "record_id" TEXT NOT NULL, "at_utc_micros" INTEGER NOT NULL, "kind" TEXT NOT NULL CHECK(kind IN ('created', 'changed', 'finalized', 'voided', 'replaced', 'reviewed')), "changes_json" TEXT NOT NULL, "reason" TEXT NULL, "revision_after" INTEGER NOT NULL CHECK(revision_after >= 0));
CREATE TABLE "saved_views" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "sheet_ref" TEXT NOT NULL, "filters_json" TEXT NOT NULL, "sort_json" TEXT NULL, "columns_json" TEXT NULL, "position" INTEGER NOT NULL, "revision" INTEGER NOT NULL CHECK(revision >= 0), PRIMARY KEY ("id"));
CREATE TABLE "shift_breaks" ("id" TEXT NOT NULL, "shift_id" TEXT NOT NULL REFERENCES work_shifts (id) ON DELETE RESTRICT, "start_utc_micros" INTEGER NOT NULL, "end_utc_micros" INTEGER NULL, "created_at_utc_micros" INTEGER NOT NULL, "updated_at_utc_micros" INTEGER NOT NULL, "revision" INTEGER NOT NULL CHECK(revision >= 0), PRIMARY KEY ("id"));
CREATE TABLE "work_shifts" ("id" TEXT NOT NULL, "employment_id" TEXT NOT NULL REFERENCES employments (id) ON DELETE RESTRICT, "agreement_id" TEXT NULL REFERENCES pay_agreements (id) ON DELETE RESTRICT, "state" TEXT NOT NULL, "start_utc_micros" INTEGER NOT NULL, "end_utc_micros" INTEGER NULL, "timezone_id" TEXT NOT NULL, "local_start_date" TEXT NOT NULL, "note" TEXT NULL, "void_reason" TEXT NULL, "replacement_shift_id" TEXT NULL REFERENCES work_shifts (id) ON DELETE RESTRICT, "replaced_shift_id" TEXT NULL REFERENCES work_shifts (id) ON DELETE RESTRICT, "created_at_utc_micros" INTEGER NOT NULL, "updated_at_utc_micros" INTEGER NOT NULL, "revision" INTEGER NOT NULL CHECK(revision >= 0), PRIMARY KEY ("id"));
CREATE UNIQUE INDEX one_active_shift
        ON work_shifts ((1))
        WHERE state IN ('running', 'onBreak')
      ;
CREATE INDEX record_events_by_record ON record_events (record_kind, record_id, id);
